{
ret = GetPixel(uv_orig) - 0.004;
vec2 d = (vec2(1.0)/uTexSize) * 2.0;
vec3 dx = ( 2.0 * GetBlur1(uv+vec2( 1.0 , 0.0 )*d) - 2.0*GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy )*0.5;
vec3 dy = ( 2.0 * GetBlur1(uv+vec2( 0.0 , 1.0 )*d) - 2.0*GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy )*0.5;
