vec2 uv_green = mix(uv_orig, uv, 1.0) + vec2(-1, 2.0)*(vec2(1.0)/uTexSize) - vec2(dx.y,dy.y)*(vec2(1.0)/uTexSize) * 3.0 + vec2(dx.x,dy.x)*(vec2(1.0)/uTexSize) * 0.0;
