vec2 uv_green = mix(uv_orig, uv, 1.0) + vec2(-1, 2.0)*(vec2(1.0)/uTexSize) - vec2(dx.y,dy.y)*(vec2(1.0)/uTexSize) * 3.0 + vec2(dx.x,dy.x)*(vec2(1.0)/uTexSize) * 0.0;
ret.y = max( GetPixel(uv_orig).z - GetPixel(uv_orig).x * 2.0, tex2d(sampler_fc_main, uv_green).y - 0.004);
vec2 uv_blue = mix(uv_orig,uv,-0.1) + vec2(dx.z,dy.z)*(vec2(1.0)/uTexSize) * 2.0;
